// Anti-aliased UI text from a pre-baked font atlas (assets/fonts/ui.font,
// generated by tools/make_font_atlas.py). Falls back to the built-in 5x7
// bitmap font when the atlas is missing.
#pragma once

#include "common.h"

enum class FontFace : uint8_t {
    BODY = 0,     // regular weight: descriptions, hints
    BOLD = 1,     // semi-bold: labels, buttons, numbers
    DISPLAY = 2   // heavy: titles and banners
};

enum class TextAlign { LEFT, CENTER, RIGHT };

struct TextStyle {
    FontFace face = FontFace::BOLD;
    float size = 20.0f;                  // em size in pixels
    SDL_Color color{255, 255, 255, 255};
    SDL_Color outline{0, 0, 0, 0};       // drawn when alpha > 0
    SDL_Color shadow{0, 0, 0, 0};        // drawn when alpha > 0
    float shadowDy = 2.0f;
    TextAlign align = TextAlign::LEFT;
};

// Loads the font atlas. Safe to call repeatedly; returns false (and text
// falls back to the bitmap font) if the file is missing or malformed.
bool textLoadFont(const std::string& path = "assets/fonts/ui.font");
bool textFontAvailable();

float textWidth(const std::string& s, FontFace face, float size);
// Distance from the top of the line box to the top of capital letters.
float textCapTop(FontFace face, float size);
float textCapHeight(FontFace face, float size);
float textLineHeight(FontFace face, float size);

// Draws one line. (x, y) is the anchor point (per align) at the top of the
// line box. Returns the line's width.
float drawTextStyled(SDL_Renderer* ren, const std::string& s, float x, float y, const TextStyle& st);

// Word-wraps to maxWidth; returns the total height used.
float drawTextWrapped(SDL_Renderer* ren, const std::string& s, float x, float y, float maxWidth,
                      const TextStyle& st, float lineGap = 1.15f);

// Builds a style in one expression.
inline TextStyle textStyle(FontFace face, float size, SDL_Color color, TextAlign align = TextAlign::LEFT) {
    TextStyle st;
    st.face = face;
    st.size = size;
    st.color = color;
    st.align = align;
    return st;
}
